import fs from 'node:fs';
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';

const siteConfig = JSON.parse(fs.readFileSync(new URL('../scripts/site-config.json', import.meta.url), 'utf8'));

let sidebar = [];
try {
  sidebar = JSON.parse(fs.readFileSync(new URL('./src/generated/sidebar.json', import.meta.url), 'utf8'));
} catch {
  // The sidebar is generated by scripts/sync-content.mjs before dev/build.
}

export default defineConfig({
  site: siteConfig.site,
  base: siteConfig.base,
  integrations: [
    starlight({
      title: siteConfig.title,
      description: siteConfig.tagline,
      defaultLocale: 'root',
      locales: {
        root: { label: '简体中文', lang: 'zh-CN' },
      },
      social: [{ icon: 'github', label: 'GitHub', href: siteConfig.repo }],
      customCss: ['./src/styles/theme.css'],
      components: {
        ThemeSelect: './src/components/ThemeSelect.astro',
      },
      head: [
        {
          tag: 'script',
          content: "try{localStorage.setItem('starlight-theme','dark')}catch{}",
        },
      ],
      expressiveCode: {
        themes: ['github-dark'],
      },
      pagefind: true,
      sidebar,
    }),
  ],
});
